func TestInstalledPackagesEmptyRelease(t *testing.T) {
	tests := []struct {
		name, line, epoch, repository string
		fromRepoquery                 bool
	}{
		{"rpm no epoch", "package 0 1  x86_64 package-1--src.rpm", "0", "", false},
		{"rpm epoch", "package 2 1  x86_64 package-1--src.rpm", "2", "", false},
		{"repoquery no epoch", "package (none) 1  x86_64 package-1--src.rpm @amzn2-core", "(none)", "amzn2-core", true},
		{"repoquery epoch", "package 2 1  x86_64 package-1--src.rpm installed", "2", "amzn2-core", true},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			o := &redhatBase{}
			var bp *models.Package
			var sp *models.SrcPackage
			var err error
			if tt.fromRepoquery {
				bp, sp, err = o.parseInstalledPackagesLineFromRepoquery(tt.line)
			} else {
				bp, sp, err = o.parseInstalledPackagesLine(tt.line)
			}
			if err != nil {
				t.Fatal(err)
			}
			if bp.Name != "package" || bp.Version != rpmVersion(tt.epoch, "1", "") || bp.Release != "" || bp.Arch != "x86_64" || bp.Repository != tt.repository {
				t.Errorf("incorrect binary package: %+v", bp)
			}
			if sp == nil || sp.Name != "package" || sp.Version != rpmVersion(tt.epoch, "1", "") || sp.Arch != "src" || !reflect.DeepEqual(sp.BinaryNames, []string{"package"}) {
				t.Errorf("incorrect source package: %+v", sp)
			}
		})
	}
	for _, tt := range []struct {
		name, line string
	}{
		{"rpm", "package 0 1  x86_64 package-1--src.rpm"},
		{"repoquery", "package 0 1  x86_64 package-1--src.rpm @amzn2-core"},
	} {
		t.Run("full "+tt.name, func(t *testing.T) {
			o := &redhatBase{base: base{Distro: config.Distro{Family: constant.Amazon, Release: "2 (Karoo)"}, log: logging.NewIODiscardLogger()}}
			bp, sp, err := o.parseInstalledPackages(tt.line)
			if err != nil {
				t.Fatal(err)
			}
			if bp["package"].Version != "1" || bp["package"].Release != "" || sp["package"].Version != "1" {
				t.Errorf("incorrect packages: binary=%+v source=%+v", bp, sp)
			}
		})
	}
}

func TestSplitFileNameValidation(t *testing.T) {
	for _, tt := range []struct {
		filename, name, version, release, epoch, arch string
	}{
		{"package-0-1-src.rpm", "package", "0", "1", "", "src"},
		{"package-0-1.el9-src.rpm", "package", "0", "1.el9", "", "src"},
		{"package-0--src.rpm", "package", "0", "", "", "src"},
		{"name-with-hyphens-0-1.src.rpm", "name-with-hyphens", "0", "1", "", "src"},
		{"2:name-with-hyphens-0-1.src.rpm", "name-with-hyphens", "0", "1", "2", "src"},
	} {
		t.Run(tt.filename, func(t *testing.T) {
			n, v, r, e, a, err := splitFileName(tt.filename)
			if err != nil || n != tt.name || v != tt.version || r != tt.release || e != tt.epoch || a != tt.arch {
				t.Errorf("got %q %q %q %q %q, %v", n, v, r, e, a, err)
			}
		})
	}
	for _, filename := range []string{"package-0-1-src", "-0-1.src.rpm", "package--1.src.rpm", "package-0.src.rpm", "package-0-1..rpm", "package-0-1.src.rpm.bak"} {
		t.Run("invalid "+filename, func(t *testing.T) {
			if _, _, _, _, _, err := splitFileName(filename); err == nil {
				t.Errorf("accepted malformed filename %q", filename)
			}
		})
	}
}
